<?php
declare(strict_types=1);namespace Vendi\Invoicing;use PDO;use RuntimeException;
final class InvoiceService{public function __construct(private PDO $db,private ?PacProviderInterface $pac=null){}
 public function createFromSale(int$b,int$branch,int$u,int$saleId,array$tax):int{$required=['rfc','tax_name','tax_zip','tax_regime','cfdi_use'];foreach($required as$k)if(trim((string)($tax[$k]??''))==='')throw new RuntimeException('Falta dato fiscal: '.$k);$this->db->beginTransaction();try{$s=$this->db->prepare("SELECT * FROM sales WHERE id=? AND business_id=? AND branch_id=? AND status='completed' FOR UPDATE");$s->execute([$saleId,$b,$branch]);$sale=$s->fetch();if(!$sale)throw new RuntimeException('Venta no disponible para facturar.');$dup=$this->db->prepare("SELECT id FROM invoices WHERE sale_id=?");$dup->execute([$saleId]);if($id=$dup->fetchColumn()){ $this->db->commit();return(int)$id;}$q=$this->db->prepare("INSERT INTO invoices(business_id,branch_id,sale_id,customer_id,user_id,status,rfc,tax_name,tax_zip,tax_regime,cfdi_use,subtotal,total) VALUES(?,?,?,?,?,'draft',?,?,?,?,?,?,?)");$q->execute([$b,$branch,$saleId,$sale['customer_id'],$u,strtoupper($tax['rfc']),$tax['tax_name'],$tax['tax_zip'],$tax['tax_regime'],$tax['cfdi_use'],$sale['subtotal'],$sale['total']]);$id=(int)$this->db->lastInsertId();$i=$this->db->prepare("SELECT si.*,p.sat_product_key,p.sat_unit_key,p.tax_object FROM sale_items si JOIN products p ON p.id=si.product_id WHERE si.sale_id=?");$i->execute([$saleId]);foreach($i->fetchAll() as$x){if(!$x['sat_product_key']||!$x['sat_unit_key']||!$x['tax_object'])throw new RuntimeException('Producto sin datos SAT: '.$x['description']);$this->db->prepare("INSERT INTO invoice_items(invoice_id,sale_item_id,product_id,description,sat_product_key,sat_unit_key,tax_object,quantity,unit_price,discount,tax,line_total) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$id,$x['id'],$x['product_id'],$x['description'],$x['sat_product_key'],$x['sat_unit_key'],$x['tax_object'],$x['qty'],$x['unit_price'],$x['discount'],$x['tax'],$x['line_total']]);}$this->db->commit();return$id;}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
 public function stamp(int$b,int$id):array{if(!$this->pac)throw new RuntimeException('Configura un PAC antes de timbrar.');$q=$this->db->prepare("SELECT * FROM invoices WHERE id=? AND business_id=? FOR UPDATE");$this->db->beginTransaction();try{$q->execute([$id,$b]);$inv=$q->fetch();if(!$inv||!in_array($inv['status'],['draft','error'],true))throw new RuntimeException('Factura no disponible para timbrar.');$it=$this->db->prepare("SELECT * FROM invoice_items WHERE invoice_id=?");$it->execute([$id]);$this->db->prepare("UPDATE invoices SET status='pending',error_message=NULL WHERE id=?")->execute([$id]);$result=$this->pac->stamp($inv,$it->fetchAll());$this->db->prepare("UPDATE invoices SET status='stamped',uuid=?,pac_provider=?,pac_reference=?,xml_path=?,pdf_path=?,stamped_at=NOW() WHERE id=?")->execute([$result['uuid'],$result['provider']??null,$result['reference']??null,$result['xml_path']??null,$result['pdf_path']??null,$id]);$this->db->commit();return$result;}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();$this->db->prepare("UPDATE invoices SET status='error',error_message=? WHERE id=?")->execute([$e->getMessage(),$id]);throw$e;}}
}